#include "../server.h"
using json=nlohmann::json; static crow::response pr(const json&j,int c=200){return crow::response{c,j.dump()};}
void registerPlaylistRoutes(TuneSphereServer&s){CROW_ROUTE(s.app,"/api/playlists")([&]{return pr(s.playlists.all());});CROW_ROUTE(s.app,"/api/playlists").methods(crow::HTTPMethod::Post)([&](const crow::request&r){auto j=json::parse(r.body,nullptr,false);if(j.is_discarded()||!j.contains("name"))return pr({{"error","name required"}},400);return pr(s.playlists.create(j["name"]),201);});CROW_ROUTE(s.app,"/api/playlists/<int>").methods(crow::HTTPMethod::Delete)([&](int id){return s.playlists.erase(id)?pr({{"deleted",id}}):pr({{"error","Not found"}},404);});CROW_ROUTE(s.app,"/api/playlists/<int>/songs/<int>").methods(crow::HTTPMethod::Post)([&](int p,int song){return s.playlists.addSong(p,song)?pr({{"ok",true}}):pr({{"error","Not found"}},404);});CROW_ROUTE(s.app,"/api/playlists/<int>/songs/<int>").methods(crow::HTTPMethod::Delete)([&](int p,int song){return s.playlists.removeSong(p,song)?pr({{"ok",true}}):pr({{"error","Not found"}},404);});}
